162:                 MortalBootstrapLocationScaffold.StatePath,
163:                 StringComparer.Ordinal) &&
164:             plan.FinalBootstrapScaffold != null &&
165:             preTurnBootstrapScaffold != null)
166:         {
167:             var settledRoot = preTurnBootstrapScaffold.DeepClone().AsObject();
168:             settledRoot["locationMaterializationRequest"] =
169:                 plan.FinalBootstrapScaffold.DeepClone();
170:             await WriteCanonicalFileAtomicAsync(
171:                 MortalBootstrapLocationScaffold.StatePath,
172:                 settledRoot.ToJsonString(JsonOpts));
173:         }
174:         await ApplyMortalLocationGovernedRewritesAsync(plan, rawNpcCore);
