281:     private async Task<JsonObject?> ReadMortalLocationObjectRootAsync(string path)
282:     {
283:         var json = await ReadCanonicalFileAsync(path);
284:         if (string.IsNullOrWhiteSpace(json))
285:             return null;
286: 
287:         try
288:         {
289:             return JsonNode.Parse(json) as JsonObject ??
290:                 throw new InvalidDataException($"{path} must have an object root.");
291:         }
292:         catch (JsonException exception)
293:         {
294:             throw new InvalidDataException($"{path} contains malformed JSON.", exception);
295:         }
296:     }
