298:     private async Task<JsonObject> ReadRequiredMortalLocationBackupAsync(
299:         string path,
300:         IReadOnlyDictionary<string, string>? backups)
301:     {
302:         if (backups == null || !backups.ContainsKey(path))
303:         {
304:             throw new InvalidOperationException(
305:                 $"Mortal location normalization requires a validated pre-turn backup for '{path}'.");
306:         }
307: 
308:         return await ReadBackupObjectAsync(path, backups) ??
309:             throw new InvalidDataException(
310:                 $"Mortal location pre-turn backup for '{path}' must be readable object JSON.");
311:     }
312: }

65:     private async Task NormalizeMortalItemsAsync(
66:         IReadOnlyDictionary<string, string>? backups,
67:         IReadOnlyList<MortalLocationStorageCoordinate>? acceptedStorageCoordinates,
68:         MortalItemAcceptedTurnNormalizationMode mode)
69:     {
70:         ArgumentNullException.ThrowIfNull(mode);
71:         if (mode is MortalItemAcceptedTurnNormalizationMode.Validated validated)
72:         {
73:             var currentRoots = validated.Snapshot.CloneCurrentProjectionRoots();
74:             IReadOnlyDictionary<string, JsonNode?> projectedRoots;
75:             if (validated.Snapshot.CloneFinalBaseline() is { } finalBaseline)
76:             {
77:                 var itemPhase = validated.Snapshot.CloneItemPhase();
78:                 if (finalBaseline.Issues.Count != 0 ||
79:                     itemPhase is null ||
80:                     itemPhase.Issues.Count != 0 ||
81:                     !validated.Snapshot.RecomputesFinalPublicationBaseline())
82:                 {
83:                     throw new InvalidDataException(
84:                         "Accepted Mortal item final publication baseline is invalid.");
85:                 }
86:                 projectedRoots = itemPhase.ItemPhaseAfterImages;
87:             }
88:             else
89:             {
90:                 var backupRoots = validated.Snapshot.CloneBackupProjectionRoots();
91:                 var identityRoot = currentRoots[MortalItemIdentityState.StatePath]
92:                     as JsonObject ?? throw new InvalidDataException(
93:                         "Accepted Mortal item projection requires its frozen identity root.");
94:                 var identity = MortalItemIdentityState.Parse(identityRoot.DeepClone());
95:                 var projected = MortalItemCanonicalProjectionPlanner.Project(
96:                     new MortalItemCanonicalProjectionInput(
97:                         validated.Snapshot.Turn,
98:                         validated.Snapshot,
99:                         validated.Snapshot.CloneRouteCatalog(),
100:                         currentRoots,
101:                         backupRoots,
102:                         identity));
103:                 if (!projected.IsValid)
104:                 {
105:                     throw new InvalidDataException(
106:                         $"Accepted Mortal item projection failed: {projected.Issues[0].Code}.");
107:                 }
108:                 projectedRoots = projected.ItemPhaseAfterImages;
109:             }
110:             foreach (var path in MortalItemCanonicalProjectionPlanner.ProjectionRootPaths)
111:             {
112:                 var after = projectedRoots[path];
113:                 if (JsonNode.DeepEquals(currentRoots[path], after))
114:                     continue;
115:                 if (after == null)
116:                 {
117:                     throw new InvalidDataException(
118:                         $"Accepted Mortal item projection cannot remove registered root '{path}'.");
119:                 }
120:                 await WriteCanonicalFileAtomicAsync(path, after.ToJsonString(JsonOpts));
121:             }
122:             return;
123:         }
124: 
125:         await NormalizeOrdinaryMortalItemsAsync(
126:             backups,
127:             acceptedStorageCoordinates,
128:             mode);
129:     }
