16:     private async Task NormalizeOrdinaryMortalItemTransfersAsync(
17:         IReadOnlyDictionary<string, string>? backups)
18:     {
19:         var currentRoots = await ReadOrdinaryMortalItemProjectionRootsAsync(
20:             backups: null);
21:         var backupRoots = await ReadOrdinaryMortalItemProjectionRootsAsync(backups);
22:         var previousCatalog = BuildOrdinaryPhysicalMortalItemCatalog(backupRoots);
23:         var currentCatalog = BuildOrdinaryPhysicalMortalItemCatalog(currentRoots);
24:         if (previousCatalog.Issues.Count > 0 || currentCatalog.Issues.Count > 0)
25:         {
26:             var issue = previousCatalog.Issues.FirstOrDefault() ?? currentCatalog.Issues[0];
27:             throw new InvalidDataException(
28:                 $"Mortal item transfer carrier authority failed: {issue.Code}.");
29:         }
30: 
31:         var acceptedTurn = await TryReadCurrentTurnNumberAsync();
32:         var accepted = await MortalItemAcceptedTransferCatalog.BuildAsync(
33:             _fs,
34:             _writeLease,
35:             previousCatalog,
36:             currentCatalog,
37:             acceptedTurn);
38:         if (accepted.Issues.Count > 0)
39:         {
40:             throw new InvalidDataException(
41:                 $"Mortal item transfer authority failed: {accepted.Issues[0].Code}.");
42:         }
43:         if (accepted.Transfers.Count == 0)
44:             return;
45: 
46:         if (currentRoots[MortalItemIdentityState.StatePath] is not JsonObject indexRoot)
47:             throw new InvalidDataException("Mortal item identity index is absent.");
48:         var transitionIds = accepted.Transfers.ToDictionary(
49:             static transfer => transfer.ItemId,
50:             static _ => "mitrn_" + Guid.NewGuid().ToString("N"),
51:             StringComparer.Ordinal);
52:         var projected = MortalItemTransferPlanner.Plan(
53:             currentRoots,
54:             MortalItemIdentityState.Parse(indexRoot.DeepClone()),
55:             accepted.Transfers,
56:             transitionIds);
57:         if (!projected.IsValid)
58:         {
59:             throw new InvalidDataException(
60:                 $"Mortal item transfer failed: {projected.Issues[0].Code}.");
61:         }
62: 
63:         foreach (var path in MortalItemCanonicalProjectionPlanner.ProjectionRootPaths)
64:         {
65:             var after = projected.Roots[path];
66:             if (JsonNode.DeepEquals(currentRoots[path], after))
67:                 continue;
68:             if (after == null)
69:                 throw new InvalidDataException(
70:                     $"Mortal item transfer cannot remove canonical root '{path}'.");
71:             await WriteCanonicalFileAtomicAsync(path, after.ToJsonString(JsonOpts));
72:         }
73:     }
