403:     private async Task NormalizeGuardiansAsync(
404:         IReadOnlyDictionary<string, string>? backups,
405:         AcceptedMechanicsPlan? acceptedMechanicsPlan)
406:     {
407:         const string path = "game_state/meta/guardians.json";
408:         var currentNode = await ReadNodeAsync(path);
409:         if (currentNode == null) return;
410: 
411:         var previous = await ReadBackupObjectAsync(path, backups);
412:         var result = CloneObject(previous ?? new JsonObject());
413:         var currentTurn = await TryReadCurrentTurnNumberAsync();
414:         var pendingPowerEvents = new List<JsonObject>();
415:         var powerJournalEntries = new List<JsonObject>();
416:         var keepQuestProgressUpdates = false;
417: 
418:         if (currentNode is JsonObject currentObj)
419:         {
420:             MergeObject(result, currentObj);
421:             if (currentObj["guardians"] is JsonArray guardians)
422:                 result["guardians"] = guardians.DeepClone();
423:             if (currentObj["activeGuardian"] is JsonObject activeGuardian)
424:                 result["activeGuardian"] = activeGuardian.DeepClone();
425:             if (currentObj["chaosSeaNavigation"] is JsonObject nav)
426:                 result["chaosSeaNavigation"] = nav.DeepClone();
427:             if (currentObj["pendingGuardianCreation"] is JsonObject pending)
428:                 result["pendingGuardianCreation"] = pending.DeepClone();
429:             if (currentObj["UpdateGuardians"] is JsonArray updates)
430:                 ApplyGuardianCommands(result, updates, currentTurn, pendingPowerEvents);
431:             if (currentObj.TryGetPropertyValue(GuardianProjectState.QuestProgressUpdatesProperty, out var questProgressUpdatesNode))
432:             {
433:                 keepQuestProgressUpdates = questProgressUpdatesNode != null;
434:                 if (questProgressUpdatesNode is JsonArray questProgressUpdates)
435:                     _ = TryApplyGuardianQuestProgressUpdates(result, questProgressUpdates, currentTurn);
436:             }
437:             if (currentObj["guardianPowerEvents"] is JsonArray powerEvents)
438:                 pendingPowerEvents.AddRange(powerEvents.OfType<JsonObject>().Select(CloneObject));
439:         }
440:         else if (currentNode is JsonArray currentArray)
441:         {
442:             result["guardians"] = currentArray.DeepClone();
443:         }
444: 
445:         if (previous is JsonObject previousObj &&
446:             previousObj[GuardianTradeRequestState.UpdateReceiptsProperty] is JsonArray previousTradeReceiptUpdates)
447:         {
448:             GuardianTradeRequestState.ApplyReceiptUpdates(result, previousTradeReceiptUpdates);
449:         }
450: 
451:         if (currentNode is JsonObject currentRootObj &&
452:             currentRootObj[GuardianTradeRequestState.UpdateReceiptsProperty] is JsonArray currentTradeReceiptUpdates)
453:         {
454:             GuardianTradeRequestState.ApplyReceiptUpdates(result, currentTradeReceiptUpdates);
455:         }
456: 
457:         if (pendingPowerEvents.Count > 0)
458:             GuardianPowerEventState.ApplyEvents(result, pendingPowerEvents, currentTurn, powerJournalEntries);
459: 
460:         if (result["guardians"] is JsonArray normalizedGuardians)
461:         {
462:             foreach (var guardian in normalizedGuardians.OfType<JsonObject>())
463:             {
464:                 AbodePowerRules.EnsureCanonicalState(guardian);
465:                 GuardianGachaChargeRules.NormalizeGuardianGachaCompanionState(guardian);
466:                 GuardianTradeRequestState.NormalizeGuardianTradeReceiptsShape(guardian);
467:             }
468: 
469:             GuardianRelationshipRules.EnsureCanonicalNetwork(normalizedGuardians);
470:         }
471: 
472:         if (result["activeGuardian"] is JsonObject activeGuardianRoot)
473:         {
474:             if (result["guardians"] is JsonArray guardiansArray &&
475:                 guardiansArray.OfType<JsonObject>().FirstOrDefault(item =>
476:                     string.Equals(GetNodeString(item["guardianId"]), GetNodeString(activeGuardianRoot["guardianId"]), StringComparison.OrdinalIgnoreCase)) is JsonObject syncedGuardian)
477:             {
478:                 result["activeGuardian"] = syncedGuardian.DeepClone();
479:             }
480:             else
481:             {
482:                 result.Remove("activeGuardian");
483:             }
484:         }
485: 
486:         RetainPlannedGuardianGachaCommands(result, acceptedMechanicsPlan);
487:         if (!keepQuestProgressUpdates)
488:             result.Remove(GuardianProjectState.QuestProgressUpdatesProperty);
489:         result.Remove(GuardianTradeRequestState.UpdateReceiptsProperty);
490:         result.Remove("guardianPowerEvents");
491:         await WriteIfChangedAsync(path, currentNode, result);
492:         if (powerJournalEntries.Count > 0)
493:             await AppendGuardianPowerJournalEntriesAsync(powerJournalEntries);
494:     }

910:     private async Task AppendGuardianPowerJournalEntriesAsync(
