914:         if (buffered.Count == 0)
915:             return;
916: 
917:         var writeLease = _writeLease ?? throw new InvalidOperationException(
918:             "Guardian power journal append requires the owning canonical write lease.");
919:         var mode = _guardianPowerJournalMode ==
