89:     private async Task NormalizeActorJournalAsync(string path, string updateProperty, string actorIdProperty, IReadOnlyDictionary<string, string>? backups)
90:     {
91:         var currentNode = await ReadNodeAsync(path);
92:         if (currentNode == null)
93:             return;
94: 
95:         var previous = await ReadBackupObjectAsync(path, backups);
96:         var result = CloneObject(previous ?? new JsonObject());
97:         var entries = ActorJournalState.EnsureEntriesArray(result, actorIdProperty, updateProperty);
98: 
99:         foreach (var entry in ActorJournalState.CollectEntries(previous, actorIdProperty, updateProperty))
100:             ActorJournalState.ApplyUpdates(result, new JsonArray(entry), actorIdProperty, updateProperty);
101: 
102:         foreach (var entry in ActorJournalState.CollectEntries(currentNode, actorIdProperty, updateProperty))
103:             ActorJournalState.ApplyUpdates(result, new JsonArray(entry), actorIdProperty, updateProperty);
104: 
105:         result[ActorJournalState.EntriesProperty] = entries;
106:         result.Remove(updateProperty);
107:         await WriteIfChangedAsync(path, currentNode, result);
108:     }
109: 
110: }
