7:     private async Task NormalizePlayerSkillStateAsync(
8:         IReadOnlyDictionary<string, string>? backups)
9:     {
10:         const string activePath = "game_state/player/skills_active.json";
11:         const string passivePath = "game_state/player/skills_passive.json";
12:         var currentActive = await ReadNodeAsync(activePath);
13:         var currentPassive = await ReadNodeAsync(passivePath);
14:         if (currentActive is null && currentPassive is null)
15:             return;
16: 
17:         JsonObject? composedActive = null;
18:         JsonObject? composedPassive = null;
19:         if (currentActive is not null)
20:         {
21:             composedActive = EffectAcceptedTurnInputComposer.ComposeSkillAcceptedRoot(
22:                 await ReadBackupNodeAsync(activePath, backups),
23:                 currentActive,
24:                 "activeSkillChanges",
25:                 "removeActiveSkills",
26:                 activePath);
27:         }
28:         if (currentPassive is not null)
29:         {
30:             composedPassive = EffectAcceptedTurnInputComposer.ComposeSkillAcceptedRoot(
31:                 await ReadBackupNodeAsync(passivePath, backups),
32:                 currentPassive,
33:                 "passiveSkillChanges",
34:                 "removePassiveSkills",
35:                 passivePath);
36:         }
37: 
38:         var capabilityIssues = MortalWoundTreatmentCapabilityContract.ValidateComposedActorCatalog(
39:             "player",
40:             "player",
41:             currentActive as JsonObject ?? new JsonObject(),
42:             activePath,
43:             currentPassive as JsonObject ?? new JsonObject(),
44:             passivePath,
45:             composedActive ?? new JsonObject(),
46:             composedPassive ?? new JsonObject());
47:         if (capabilityIssues.Count > 0)
48:         {
49:             throw new InvalidOperationException(
50:                 "Mortal wound-treatment capability normalizer invariant failed: " +
51:                 capabilityIssues[0].Code);
52:         }
53: 
54:         if (currentActive is not null && composedActive is not null)
55:             await WriteIfChangedAsync(activePath, currentActive, composedActive);
56:         if (currentPassive is not null && composedPassive is not null)
57:             await WriteIfChangedAsync(passivePath, currentPassive, composedPassive);
58:     }

867:     internal static JsonObject ComposeSkillAcceptedRoot(
868:         JsonNode? preTurnRoot,
869:         JsonNode? acceptedRoot,
870:         string changeProperty,
871:         string removalProperty,
872:         string? path = null)
873:     {
874:         var issues = new List<ValidationIssue>();
875:         var result = ComposeSkillAcceptedRootCore(
876:             preTurnRoot,
877:             acceptedRoot,
878:             changeProperty,
879:             removalProperty,
880:             path ?? changeProperty,
881:             issues);
882:         if (issues.Count > 0)
883:         {
884:             throw new InvalidDataException(
885:                 $"Skill composition is ambiguous at '{path ?? changeProperty}': " +
886:                 issues[0].Code);
887:         }
888:         return result;
889:     }

919:     private static JsonObject ComposeSkillAcceptedRootCore(
920:         JsonNode? preTurnRoot,
921:         JsonNode? acceptedRoot,
922:         string changeProperty,
923:         string removalProperty,
924:         string path,
925:         List<ValidationIssue> issues)
926:     {
927:         var skills = EnumerateSkillEntries(preTurnRoot, changeProperty)
928:             .Select(static skill => skill.DeepClone().AsObject())
929:             .ToList();
930:         var updateIndex = 0;
931:         foreach (var skill in EnumerateSkillEntries(acceptedRoot, changeProperty))
932:         {
933:             ApplySkillUpdate(
934:                 skills,
935:                 skill,
936:                 $"{path}.{changeProperty}[{updateIndex++}]",
937:                 issues);
938:         }
939: 
940:         if (acceptedRoot is JsonObject acceptedObject &&
941:             acceptedObject[removalProperty] is JsonArray removals)
942:         {
943:             var removalIndex = 0;
944:             foreach (var removal in removals)
945:             {
946:                 if (!TryReadExact(removal, out var selector))
947:                 {
948:                     removalIndex++;
949:                     continue;
950:                 }
951:                 ApplySkillRemoval(
952:                     skills,
953:                     selector,
954:                     $"{path}.{removalProperty}[{removalIndex++}]",
955:                     issues);
956:             }
957:         }
958: 
959:         ValidateComposedSkillNames(skills, path, changeProperty, issues);
960:         var result = new JsonObject
961:         {
962:             [changeProperty] = new JsonArray(
963:                 skills.Select(static skill => (JsonNode?)skill).ToArray())
964:         };
965:         CopySkillMetadata(preTurnRoot, result);
966:         CopySkillMetadata(acceptedRoot, result);
967:         return result;
